/// <summary>
///    Performs lookup on the <c>EcoResProduct</c> table from a <c>FormStringControl</c> form control
///    bound to a product ID field.
/// </summary>
/// <param name="_formStringControl">
///    A <c>FormStringControl</c> form control bound to a product ID field.
/// </param>
/// <returns>
///    A record in the <c>EcoResProduct</c> table that is selected by the user.
/// </returns>
public EcoResProduct performLookupString(FormStringControl _formStringControl)
{
    Args args = new Args();
    args.name(formStr(EcoResProductLookup));
    args.caller(this);

    args.parmObject(this);

    args.lookupField(fieldNum(EcoResProduct, RecId));
    args.lookupValue(_formStringControl.valueStr());

    FormRun formRun = classfactory.formRunClass(args);
    formRun.init();        
    _formStringControl.performFormLookup(formRun);
    EcoResProduct ecoResProduct = formRun.selectRecordModeSelectedRecord() as EcoResProduct;

    return ecoResProduct;
}
